        ),
        newsRepo.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
      ]);

      if (!mounted) return;
      setState(() {
        _refreshKey++;
      });
    } catch (_) {
      /* ignore — страницы покажут кэш */
    }
  }

  @override
